FT_product_listing.invariants_dsl:
spec ProductListing {
    field category: String {
        value IN ["electronics", "home-office", "gaming", "accessories"];
    }
    field price_usd: Number {
        value >= 1.0;
        value <= 5000.0;
    }
    field description: String {
    }
}

FT_support_ticket.invariants_dsl:
spec SupportTicket {
    field priority: String {
        value IN ["low", "normal", "high", "urgent"];
    }
    field subject: String {
    }
    field body: String {
    }
}

FT_article_summary.invariants_dsl:
spec ArticleSummary {
    field category: String {
        value IN ["politics", "technology", "business", "science", "world"];
    }
    field word_count: Integer {
        value >= 50;
        value <= 2000;
    }
    field summary: String {
    }
}
